import {
  Output,
  EventEmitter,
  Directive,
  HostListener,
  HostBinding,
} from '@angular/core';

@Directive({
  selector: '[dfSkipLink]',
})
export class SkipLinkDirective {
  @HostBinding() class = 'list-group-item list-group-item-action';

  @Output() inFocus: EventEmitter<boolean>;
  @HostListener('focus')
  @HostListener('click')
  public onFocus() {
    this.inFocus.emit(true);
  }
  @HostListener('blur')
  public onBlur() {
    this.inFocus.emit(false);
  }

  constructor() {
    this.inFocus = new EventEmitter();
  }
}
