import { SkipLinkDirective } from '../../directives/skip-link.directive';
import {
  Component,
  ContentChildren,
  QueryList,
  AfterContentInit,
  OnDestroy,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
} from '@angular/core';
import { merge, Subscription } from 'rxjs';

@Component({
  selector: 'df-skip-links-container',
  templateUrl: './skip-links-container.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SkipLinksContainerComponent
  implements AfterContentInit, OnDestroy {
  @ContentChildren(SkipLinkDirective)
  private links: QueryList<SkipLinkDirective>;
  _inFocus = false;
  private focusSubscription: Subscription;

  constructor(private changeDetector: ChangeDetectorRef) {}

  ngAfterContentInit() {
    if (!this.links.length) {
      return;
    }
    this.focusSubscription = merge(
      ...this.links.map(link => link.inFocus)
    ).subscribe((focus: boolean) => {
      this._inFocus = focus;
      this.changeDetector.detectChanges();
    });
  }

  ngOnDestroy() {
    this.focusSubscription.unsubscribe();
  }
}
